def skill():
    tbl = {1.0: Rational('0.341'), 1.5: Rational('0.433'), 2.0: Rational('0.477'), 2.5: Rational('0.494')}
    a = Symbol('a')
    a0 = solve(Eq(448*a/24, 56), a)[0]
    p = a0/24
    n = 448
    sd = sqrt(n*p*(1 - p))
    mean = n*p
    z1, z2 = (49 - mean)/sd, (70 - mean)/sd
    return 1000*(tbl[abs(float(z1))] + tbl[abs(float(z2))])

def standard():
    tbl = {1.0: Rational('0.341'), 1.5: Rational('0.433'), 2.0: Rational('0.477'), 2.5: Rational('0.494')}
    cands = []
    for a in range(1, 7):
        # 한 번 시행에서 기록 2의 확률
        p = Fraction(0)
        for eye in range(1, 7):
            if eye <= a:
                p += Fraction(1, 6) * Fraction(1, 4)
        if 448*p == 56:
            cands.append((a, p))
    assert len(cands) == 1
    p = Rational(cands[0][1].numerator, cands[0][1].denominator)
    n = 448
    mean, sd = n*p, sqrt(n*p*(1 - p))
    z1, z2 = (49 - mean)/sd, (70 - mean)/sd
    return 1000*(tbl[abs(float(z1))] + tbl[abs(float(z2))])

def unique():
    return [standard()]
